const express = require('express');
const { RateLimiterPostgres } = require('rate-limiter-flexible');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const rateLimiter = new RateLimiterPostgres({
  storeClient: pool,
  tableName: 'partner_rate_limits',
  points: 1000,
  duration: 3600
});

app.post('/api/admin/rate-limits/reset-key', async (req, res) => {
  if (!req.user || req.user.role !== 'PLATFORM_ADMIN') {
    return res.status(403).json({ error: 'Platform admin privileges required to reset rate limits' });
  }

  const { rateLimitKey } = req.body;

  const wasDeleted = await rateLimiter.delete(rateLimitKey);
  res.json({ success: true, key: rateLimitKey, reset: wasDeleted });
});

app.listen(9003);
